#!/usr/bin/env python3
"""Embeds port/assets/server_ui into a static C file for the dedicated server."""

import hashlib
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
UI = ROOT / "port/assets/server_ui"
FILES = (
    ("index.html", "text/html; charset=utf-8"),
    ("app.js", "text/javascript; charset=utf-8"),
    ("app.css", "text/css; charset=utf-8"),
    ("icon.svg", "image/svg+xml"),
)

def main() -> None:
    output_path = Path(sys.argv[1]) if len(sys.argv) > 1 else (ROOT / "port/linux/game/server_ui_embedded.c")
    lines = [
        "/* generated by tools/embed_server_ui.py from port/assets/server_ui: do not edit */",
        "",
        "#include \"cseries.h\"",
        "#include \"server_web.h\"",
        "",
        "#if !defined(_WIN32) && !defined(HALO_ANDROID) && !defined(HALO_ARM64_GUEST) && !defined(HALO_WEB)",
        "",
    ]
    table = []
    for index, (name, content_type) in enumerate(FILES):
        path = UI / name
        if not path.is_file():
            continue
        data = path.read_bytes()
        etag = hashlib.sha256(data).hexdigest()[:16]
        lines.append(f"static const unsigned char server_ui_file_{index}[] =")
        lines.append("{")
        for start in range(0, len(data), 24):
            lines.append("\t" + ", ".join(str(byte) for byte in data[start:start + 24]) + ",")
        lines.append("\t0")
        lines.append("};")
        table.append(f'\t{{ "{name}", "{content_type}", server_ui_file_{index}, {len(data)}UL, "{etag}" }},')

    lines.append("")
    lines.append("const struct server_ui_asset server_ui_assets[] =")
    lines.append("{")
    lines += table or ['\t{ "", "", 0, 0, "" },']
    lines.append("};")
    lines.append(f"const unsigned long server_ui_asset_count = {len(table)}UL;")
    lines.append("")
    lines.append("#endif /* !defined(_WIN32) && ... */")
    lines.append("")

    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text("\n".join(lines) + "\n")
    print(f"Generated {output_path} ({len(table)} assets)")

if __name__ == "__main__":
    main()
